        numeric:N(24.8,0.01,'u',[L('0,600+0,400=1.','0.600+0.400=1.'),L('0,600×24,0=14,4 u; 0,400×26,0=10,4 u.','0.600×24.0=14.4 u; 0.400×26.0=10.4 u.'),L('14,4+10,4=24,8 u.','14.4+10.4=24.8 u.')])
