        steps:[L('Calcula primero la masa de CaCO₃ puro.','First calculate the mass of pure CaCO₃.'),L('Convierte a moles y aplica la razón 1:1.','Convert to moles and apply the 1:1 ratio.'),L('Convierte los moles de CO₂ a gramos.','Convert CO₂ moles to grams.')],
        checks:[L('Apliqué la pureza una sola vez.','I applied purity only once.'),L('Cancelé gramos y moles de las sustancias correctas.','I cancelled grams and moles of the correct substances.')],
        numeric:N(4.4,0.01,'g',[L('m(CaCO₃)=12,5×0,800=10,0 g.','m(CaCO₃)=12.5×0.800=10.0 g.'),L('n(CaCO₃)=10,0/100,0=0,100 mol=n(CO₂).','n(CaCO₃)=10.0/100.0=0.100 mol=n(CO₂).'),L('m(CO₂)=0,100×44,0=4,40 g.','m(CO₂)=0.100×44.0=4.40 g.')])
